-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.unpublish_log_entries(max_entries integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'total', (select count(*) from public.unpublish_log),
    'entries', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', u.id,
               'kind', u.kind,
               'itemId', u.item_id,
               'title', u.title,
               'reason', u.reason,
               'by', u.requested_by,
               'doneAt', u.done_at,
               'removed', u.removed,
               'onSite', case u.kind
                           when 'note' then exists (select from public.notes n where n.id = u.item_id)
                           when 'quiz' then exists (select from public.quizzes q where q.id = u.item_id)
                           when 'deck' then exists (select from public.anki_decks d where d.id = u.item_id)
                         end)
             order by u.done_at desc, u.id desc)
        from (select l.* from public.unpublish_log l
               order by l.done_at desc, l.id desc
               limit greatest(1, least(coalesce(max_entries, 200), 500))) u), '[]'::jsonb));
$function$;

grant execute on function public.unpublish_log_entries(max_entries integer) to service_role;
